/// <summary>
/// Runs <c>ARBCodeExtensionPopulateService</c>; asynchronous by default because it reads the extension
/// maps of all installed packages.
/// </summary>
class ARBCodeExtensionPopulateController extends SysOperationServiceController
{
}

Method.Source:
protected void new(IdentifierName _className = '', IdentifierName _methodName = '', SysOperationExecutionMode _executionMode = SysOperationExecutionMode::ReliableAsynchronous)
{
    super(classStr(ARBCodeExtensionPopulateService), methodStr(ARBCodeExtensionPopulateService, populateCodeExtensions), _executionMode);
}

/// <summary>
/// Creates a new controller.
/// </summary>
/// <returns>A new <c>ARBCodeExtensionPopulateController</c>.</returns>
public static ARBCodeExtensionPopulateController construct()
{
    return new ARBCodeExtensionPopulateController();
}

public static void main(Args _args)
{
    ARBCodeExtensionPopulateController controller = ARBCodeExtensionPopulateController::construct();

    controller.startOperation();
}

public LabelType parmDialogCaption(LabelType _dialogCaption = dialogCaption)
{
    // Caption is always overridden to ensure a consistent batch job description
    return "@AOTBrowser:PopulateCodeExtensions";
}
